const { config: { theme, isDark }, computedTheme, setTheme, toggleTheme } =
  useAppContext();

// theme         'light' | 'dark' | 'auto'   what the user picked
// computedTheme 'light' | 'dark'            what is actually painted
// isDark        boolean                     shorthand for computedTheme === 'dark'

